#!/bin/bash
set -e

# ==============================================================
# kaviancrypto v7.4 Pro Terminal - Complete All-in-One Installer
# Updates in v7.4:
#   - Replaced Daily Report with Monthly Report (30D) alongside
#     Weekly Report (7D) across Overview KPIs, Overview buttons,
#     Telegram & Reports settings, and Auto Scheduler (Month-End)
#   - Strict 31-Day Closed-Trade Auto-Archive Retention Policy:
#       * Closed positions older than 31 days are auto-pruned
#       * Keeps panel fast & lightweight while preserving full 30D
#         Monthly P&L report accuracy
#       * OPEN positions are always preserved regardless of age
# + Split Check TP/SL Now & Visual TP/SL Report + Working Manual Exit
# + Strategy Studio Pro (Per-Strategy Parameters Menu + Presets +
#   Multi-TF Matrix + 500-Bar Walk-Forward Backtester)
# + Unified Obsidian Gold Pro Palette (Obsidian & Bento HUD)
# Fresh Install + Safe Repair/Upgrade (Preserves config.json,
# active_trades.json, sent_signals.json, strategy_presets.json
# & custom_strategy.py)
# ==============================================================

APP_DIR="/opt/kaviancrypto"
PORT="8888"

echo "========================================================"
echo "  kaviancrypto v7.4 Pro - All-in-One Installer & Upgrade"
echo "  Weekly/Monthly Reports + 31-Day Auto-Archive Retention"
echo "========================================================"

echo "=== [1/6] Stopping existing service (if running) & preparing $APP_DIR ==="
systemctl stop kaviancrypto.service 2>/dev/null || true
mkdir -p "$APP_DIR"
cd "$APP_DIR"

SCRIPT_SRC="$(readlink -f "$0" 2>/dev/null || echo "$0")"
if [ -f "$SCRIPT_SRC" ] && [ "$SCRIPT_SRC" != "$APP_DIR/install_kaviancrypto_v7_4.sh" ]; then
    cp -f "$SCRIPT_SRC" "$APP_DIR/install_kaviancrypto_v7_4.sh" 2>/dev/null || true
    chmod +x "$APP_DIR/install_kaviancrypto_v7_4.sh" 2>/dev/null || true
fi

echo "=== [2/6] Installing system prerequisites ==="
apt-get update -y
apt-get install -y python3 python3-venv python3-pip curl

echo "=== [3/6] Extracting verified kaviancrypto v7.4 core files ==="
